"""Reviewed question/SQL pairs used as few-shot retrieval examples."""

GOLDEN_EXAMPLES = [
    {"id":"ex01","question":"最近三个月各渠道销售额趋势","metrics":["revenue"],"dimensions":["month","channel"],"sql":"SELECT strftime('%Y-%m', o.order_time) AS month, u.channel, SUM(o.amount) AS revenue FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY month,u.channel ORDER BY month,u.channel;"},
    {"id":"ex02","question":"各渠道付费率及环比变化","metrics":["pay_rate"],"dimensions":["channel","month"],"sql":"SELECT u.channel, strftime('%Y-%m',o.order_time) AS month, COUNT(DISTINCT o.user_id)*1.0/NULLIF(COUNT(DISTINCT e.user_id),0) AS pay_rate FROM users u LEFT JOIN orders o ON o.user_id=u.user_id AND o.status='paid' LEFT JOIN user_events e ON e.user_id=u.user_id AND e.event_type='active' WHERE o.order_time BETWEEN :start AND :end GROUP BY u.channel,month;"},
    {"id":"ex03","question":"销售额下降最明显的月份","metrics":["revenue"],"dimensions":["month"],"sql":"WITH monthly AS (SELECT strftime('%Y-%m',order_time) month,SUM(amount) revenue FROM orders WHERE status='paid' AND order_time BETWEEN :start AND :end GROUP BY month) SELECT month,revenue,revenue-LAG(revenue) OVER(ORDER BY month) AS delta FROM monthly ORDER BY delta LIMIT 1;"},
    {"id":"ex04","question":"不同城市客单价","metrics":["aov"],"dimensions":["city"],"sql":"SELECT u.city,SUM(o.amount)*1.0/NULLIF(COUNT(DISTINCT o.order_id),0) AS aov FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY u.city;"},
    {"id":"ex05","question":"活跃用户最多的渠道","metrics":["active_users"],"dimensions":["channel"],"sql":"SELECT u.channel,COUNT(DISTINCT e.user_id) active_users FROM user_events e JOIN users u ON u.user_id=e.user_id WHERE e.event_type='active' AND e.event_time BETWEEN :start AND :end GROUP BY u.channel ORDER BY active_users DESC LIMIT 1;"},
    {"id":"ex06","question":"注册后7天支付转化","metrics":["conversion_rate"],"dimensions":[],"sql":"SELECT COUNT(DISTINCT o.user_id)*1.0/NULLIF(COUNT(DISTINCT u.user_id),0) AS conversion_rate FROM users u LEFT JOIN orders o ON o.user_id=u.user_id AND o.status='paid' AND julianday(o.order_time)-julianday(u.register_time) BETWEEN 0 AND 7 WHERE u.register_time BETWEEN :start AND :end;"},
    {"id":"ex07","question":"不同设备付费率","metrics":["pay_rate"],"dimensions":["device_type"],"sql":"SELECT u.device_type,COUNT(DISTINCT o.user_id)*1.0/NULLIF(COUNT(DISTINCT e.user_id),0) pay_rate FROM users u LEFT JOIN orders o ON o.user_id=u.user_id AND o.status='paid' LEFT JOIN user_events e ON e.user_id=u.user_id AND e.event_type='active' WHERE u.register_time BETWEEN :start AND :end GROUP BY u.device_type;"},
    {"id":"ex08","question":"每月支付订单数","metrics":["orders"],"dimensions":["month"],"sql":"SELECT strftime('%Y-%m',order_time) month,COUNT(*) orders FROM orders WHERE status='paid' AND order_time BETWEEN :start AND :end GROUP BY month ORDER BY month;"},
    {"id":"ex09","question":"各城市销售额","metrics":["revenue"],"dimensions":["city"],"sql":"SELECT u.city,SUM(o.amount) revenue FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY u.city;"},
    {"id":"ex10","question":"各渠道注册用户数","metrics":["registered_users"],"dimensions":["channel"],"sql":"SELECT channel,COUNT(DISTINCT user_id) registered_users FROM users WHERE register_time BETWEEN :start AND :end GROUP BY channel;"},
    {"id":"ex11","question":"各渠道付费用户数","metrics":["paid_users"],"dimensions":["channel"],"sql":"SELECT u.channel,COUNT(DISTINCT o.user_id) paid_users FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY u.channel;"},
    {"id":"ex12","question":"各城市复购率","metrics":["repeat_rate"],"dimensions":["city"],"sql":"WITH p AS (SELECT user_id,COUNT(*) n FROM orders WHERE status='paid' AND order_time BETWEEN :start AND :end GROUP BY user_id) SELECT u.city,SUM(n>=2)*1.0/NULLIF(COUNT(p.user_id),0) repeat_rate FROM p JOIN users u ON u.user_id=p.user_id GROUP BY u.city;"},
    {"id":"ex13","question":"各渠道复购用户数","metrics":["repeat_users"],"dimensions":["channel"],"sql":"WITH p AS (SELECT user_id FROM orders WHERE status='paid' AND order_time BETWEEN :start AND :end GROUP BY user_id HAVING COUNT(*)>=2) SELECT u.channel,COUNT(*) repeat_users FROM p JOIN users u ON u.user_id=p.user_id GROUP BY u.channel;"},
    {"id":"ex14","question":"各品类销售额","metrics":["revenue"],"dimensions":["category"],"sql":"SELECT p.category,SUM(o.amount) revenue FROM orders o JOIN products p ON p.product_id=o.product_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY p.category;"},
    {"id":"ex15","question":"各设备销售额","metrics":["revenue"],"dimensions":["device_type"],"sql":"SELECT u.device_type,SUM(o.amount) revenue FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY u.device_type;"},
    {"id":"ex16","question":"最近一个月活跃用户数","metrics":["active_users"],"dimensions":[],"sql":"SELECT COUNT(DISTINCT user_id) active_users FROM user_events WHERE event_type='active' AND event_time BETWEEN :start AND :end;"},
    {"id":"ex17","question":"最近一个月销售额","metrics":["revenue"],"dimensions":[],"sql":"SELECT SUM(amount) revenue FROM orders WHERE status='paid' AND order_time BETWEEN :start AND :end;"},
    {"id":"ex18","question":"按渠道看订单数和客单价","metrics":["orders","aov"],"dimensions":["channel"],"sql":"SELECT u.channel,COUNT(*) orders,SUM(o.amount)*1.0/NULLIF(COUNT(*),0) aov FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='paid' AND o.order_time BETWEEN :start AND :end GROUP BY u.channel;"},
    {"id":"ex19","question":"转化率","metrics":["conversion_rate"],"dimensions":[],"clarification_required":True,"sql":None},
    {"id":"ex20","question":"退款订单金额","metrics":["revenue"],"dimensions":[],"sql":"SELECT SUM(refund_amount) refund_amount FROM orders WHERE status='refunded' AND order_time BETWEEN :start AND :end;"}
]
